{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Konklusionen ('Nej', arbejdsophør giver ikke i sig selv ret) og beskrivelsen af Udbetaling Danmarks vurdering stemmer med ekspertrubrikken og afsnit 3.4.1.3. Ingen væsentlige juridiske fejl."},
    "c02_required_elements_complete": {"label": "met", "reason": "Alle tre kritiske elementer er med: arbejdets karakter holdes op mod funktionsnedsættelsen, sagens øvrige oplysninger bruges til at vurdere andre typer arbejde, og skånehensyn/mindre omfang indgår."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: om arbejdsophør i sig selv giver ret (nej), og hvad Udbetaling Danmark vurderer."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (hverken lov, bekendtgørelse eller vejledning)."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så det kan ikke vurderes, om en kilde understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Indholdet svarer til vejledningens afsnit 3.4.1.3 og tilføjer ingen ny regel, betingelse eller myndighed. Påstanden om, at arbejdsophør ikke i sig selv giver ret, ligger i forlængelse af materialet og ekspertrubrikken."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Svaret fastholder, at ophøret ikke i sig selv afgør retten, og at ikke-fysisk belastende arbejde er et eksempel ('eksempelvis'), ikke en selvstændig betingelse. 'Eventuelt med skånehensyn eller i mindre omfang' er bevaret."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Konklusionen følger af de beskrevne vurderingstrin, og der er ingen indbyrdes modstrid."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Formuleringer som 'vurderer', 'eventuelt' og 'eksempelvis' gengiver vejledningens skønsprægede modalitet uden at gøre noget absolut. 'Nej' gælder kun 'i sig selv'."}
  },
  "xhaile_coverage": {
    "A22": {"label": "yes", "reason": "Svaret behandler situationen, hvor ansøgeren er ophørt i arbejde på grund af funktionsnedsættelsen, og at der så ses på arbejdets karakter i forhold til funktionsnedsættelsen."},
    "A23": {"label": "yes", "reason": "Svaret angiver, at Udbetaling Danmark vurderer, om ansøgeren ud fra sagens øvrige oplysninger kan varetage andre typer arbejde, eventuelt med skånehensyn eller i mindre omfang, samt gener og skånebehov."}
  },
  "overall_notes": "Indholdet er juridisk korrekt og komplet i forhold til rubrikken, men svaret nævner ingen kilder, så C04 er not_met, og C05 og C06 er not_assessable efter kildereglen."
}

